$h = 'D:\GITHUB  Project\sangam-handoff'
$ts = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ')
$enc = New-Object System.Text.UTF8Encoding($false)
function Board($kind, $text, $to) {
  if ($text.Contains('|') -or $to.Contains('|')) { throw "pipe in text: $text" }
  [IO.File]::AppendAllText("$h\WAVE4-SYNC-BOARD.md", "$ts | W4-I/B69 | $kind | $text | $to`n", $enc)
}
function Claim($text) {
  if ($text.Contains('|')) { throw "pipe in claim" }
  [IO.File]::AppendAllText("$h\FILE-CLAIMS.md", "$ts B69 $text`n", $enc)
}

